INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20I2D84', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher recruited 120 volunteers from a campus fitness center and randomly assigned 60 to follow a high-protein diet and 60 to follow a standard diet for 12 weeks. The high-protein group lost an average of $3.4$ more pounds than the standard diet group, and the difference was statistically significant. Which of the following is a valid conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"The high-protein diet causes greater weight loss than the standard diet for all adults."},{"key":"B","text":"There is an association between the high-protein diet and weight loss, but a causal relationship cannot be established."},{"key":"C","text":"The high-protein diet causes greater weight loss than the standard diet among people similar to those who use this campus fitness center."},{"key":"D","text":"The results are invalid because the participants were volunteers rather than randomly selected."}]$lyceon_json$::jsonb, 'C', NULL, E'Because the study used random assignment, a causal conclusion about the effect of the high-protein diet is justified. However, the participants were volunteers from a specific campus fitness center, not a random sample of all adults, so the results can only be generalized to people similar to those in the study population. The claim that the diet causes greater weight loss for all adults overgeneralizes beyond the sampled population. The claim that causation cannot be established ignores the random assignment, which is precisely what allows causal inference. The assertion that the results are invalid because participants volunteered confuses random selection (which affects generalizability) with random assignment (which affects causal inference) — the study''s causal conclusion is valid for the study population even though participants volunteered.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230YEPU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $14$ inches and a width of $9$ inches. What is the area of the rectangle, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$46$"},{"key":"C","text":"$126$"},{"key":"D","text":"$252$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $14 \\times 9 = 126$ square inches. The answer $23$ adds the two dimensions ($14 + 9$) instead of multiplying. The answer $46$ computes the perimeter ($2 \\times 14 + 2 \\times 9 = 46$) instead of the area. The answer $252$ doubles the area, perhaps computing $2 \\times 14 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24XB9MD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A painter can cover $130$ square feet in $3$ hours using paint that costs $\\$17$ per gallon, where each gallon covers $65$ square feet. If the painter works for $9$ hours, what is the total cost of paint used?', NULL, $lyceon_json$[{"key":"A","text":"$\\$51$"},{"key":"B","text":"$\\$102$"},{"key":"C","text":"$\\$34$"},{"key":"D","text":"$\\$68$"}]$lyceon_json$::jsonb, 'B', NULL, E'In $9$ hours, the painter covers $\\frac{130}{3} \\times 9 = 390$ square feet. Each gallon covers $65$ square feet, so $\\frac{390}{65} = 6$ gallons are needed. At $\\$17$ per gallon, the total cost is $6 \\times 17 = \\$102$. The value $\\$51$ comes from using only $3$ gallons, as if the painter worked for half the time. The value $\\$34$ results from computing only $2$ gallons. The value $\\$68$ comes from using $4$ gallons, which could arise from miscalculating the area covered.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2547MHJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A random sample of 750 households in a city found that $43\\%$ use solar panels, with a margin of error of $\\pm 2.9$ percentage points at $95\\%$ confidence. A city official claims that more than $40\\%$ of all households in the city use solar panels. Which of the following best evaluates the official''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the entire confidence interval, from $40.1\\%$ to $45.9\\%$, is above $40\\%$."},{"key":"B","text":"The claim is supported because $43\\%$ is greater than $40\\%$."},{"key":"C","text":"The claim is not supported because the margin of error means the true value could be below $40\\%$."},{"key":"D","text":"The claim is not supported because the sample size of 750 is too small to draw conclusions about all households."}]$lyceon_json$::jsonb, 'A', NULL, E'The $95\\%$ confidence interval is $43\\% \\pm 2.9\\%$, which spans from $40.1\\%$ to $45.9\\%$. Since the entire interval lies above $40\\%$, the data support the claim that more than $40\\%$ of households use solar panels. Simply noting that $43\\% > 40\\%$ without considering the margin of error is incomplete reasoning — the margin of error must be checked. The assertion that the true value could be below $40\\%$ is arithmetically incorrect, because $43\\% - 2.9\\% = 40.1\\%$, which is still above $40\\%$. The claim that 750 households is too small reflects a misunderstanding; a random sample of 750 is generally sufficient for estimating a population proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25LBSBW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers at a hospital reviewed records of 83 patients with knee injuries. They found that the 47 patients who chose physical therapy had an average recovery time of $6.2$ weeks, while the 36 patients who chose medication alone had an average recovery time of $8.7$ weeks. Which of the following conclusions is best supported by the study?', NULL, $lyceon_json$[{"key":"A","text":"Physical therapy causes faster recovery from knee injuries than medication alone."},{"key":"B","text":"There is an association between choosing physical therapy and shorter recovery times, but a causal conclusion is not justified."},{"key":"C","text":"Medication delays recovery from knee injuries compared with no treatment."},{"key":"D","text":"The difference in recovery times is explained by the unequal sizes of the two groups."}]$lyceon_json$::jsonb, 'B', NULL, E'Because patients chose their own treatment rather than being randomly assigned, this is an observational study. Observational studies can identify associations but cannot establish causation, since confounding variables (such as injury severity or patient fitness level) may explain the difference. The claim that physical therapy causes faster recovery overstates what an observational study can support. The claim that medication delays recovery compared with no treatment introduces a comparison group (no treatment) not present in the study. Attributing the difference in recovery times to unequal group sizes reflects a misunderstanding — differences in group size do not by themselves explain differences in outcomes.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26CRLT1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $3(2x - 7) + 4 = 5x + 11$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$24$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing on the left side gives $6x - 21 + 4 = 5x + 11$, which simplifies to $6x - 17 = 5x + 11$. Subtracting $5x$ from both sides yields $x - 17 = 11$, and adding $17$ gives $x = 28$. The value $24$ results from combining $-21 + 4$ incorrectly as $-17$ but then only adding $17 - 6 = 11$ without properly isolating $x$. The value $6$ comes from an arithmetic slip in combining like terms, and $-6$ arises from a sign error when moving terms across the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274RBTA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A line of best fit for a data set is given by $y = 2.3x + 11$. Using this model, what is the predicted value of $y$ when $x = 13$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40.9', ARRAY['40.9'], E'Substituting $x = 13$ into the equation: $y = 2.3(13) + 11 = 29.9 + 11 = 40.9$. The predicted value is $40.9$. A common error is computing $2.3 \\times 13$ incorrectly, for example getting $29.3$ and then $40.3$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27ETM5U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'After a $15\\%$ increase, the population of a town is $4{,}370$. What was the population before the increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3800', ARRAY['3800'], E'Let the original population be $p$. After a $15\\%$ increase, the population is $1.15p = 4{,}370$. Solving for $p$: $p = \\frac{4370}{1.15} = 3{,}800$. The answer is $3{,}800$. A common error is computing $4370 \\times 0.85 = 3{,}714.5$, which incorrectly applies the percentage to the final value rather than the original.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27HHS0P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. If one angle measures $47^\\circ$, what is the measure of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$43^\\circ$"},{"key":"B","text":"$133^\\circ$"},{"key":"C","text":"$137^\\circ$"},{"key":"D","text":"$47^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'Supplementary angles sum to $180^\\circ$. The other angle is $180^\\circ - 47^\\circ = 133^\\circ$. The answer $43^\\circ$ results from confusing supplementary with complementary angles (which sum to $90^\\circ$). The answer $137^\\circ$ comes from an arithmetic error when subtracting from $180$. The answer $47^\\circ$ incorrectly assumes the angles are equal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2834I99', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A company charges a flat fee plus a per-mile rate for deliveries. A $13$-mile delivery costs $\\$41.50$, and a $29$-mile delivery costs $\\$73.50$. What is the flat fee, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15.5', ARRAY['31/2', '15.5'], E'Let the flat fee be $b$ and the per-mile rate be $m$. The two deliveries give the system $b + 13m = 41.50$ and $b + 29m = 73.50$. Subtracting the first equation from the second yields $16m = 32$, so $m = 2$. Substituting back: $b + 13(2) = 41.50$, giving $b + 26 = 41.50$, so $b = 15.50$. A common error is computing the rate incorrectly by dividing $73.50 - 41.50 = 32$ by $29 + 13 = 42$ instead of $29 - 13 = 16$. Another error is finding the per-mile rate but reporting it instead of the flat fee.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283WL23', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The linear function $f$ is defined by $f(x) = -2x + 9$. If $f(a) = f(2a + 3)$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$1$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Evaluating both sides: $f(a) = -2a + 9$ and $f(2a + 3) = -2(2a + 3) + 9 = -4a - 6 + 9 = -4a + 3$. Setting these equal gives $-2a + 9 = -4a + 3$. Adding $4a$ to both sides yields $2a + 9 = 3$, and subtracting $9$ gives $2a = -6$, so $a = -3$. The value $3$ results from a sign error when solving $2a = -6$. The value $-6$ comes from stopping at $2a = -6$ without dividing by $2$. The value $1$ arises from an arithmetic slip when combining like terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28N029B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane has center $(2, -3)$ and passes through the point $(14, 2)$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 2)^2 + (y + 3)^2 = 169$"},{"key":"B","text":"$(x + 2)^2 + (y - 3)^2 = 169$"},{"key":"C","text":"$(x - 2)^2 + (y + 3)^2 = 13$"},{"key":"D","text":"$(x - 14)^2 + (y - 2)^2 = 169$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. With center $(2, -3)$, the equation begins $(x - 2)^2 + (y + 3)^2 = r^2$. The radius is the distance from the center to $(14, 2)$: $r = \\sqrt{(14 - 2)^2 + (2 - (-3))^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$. So $r^2 = 169$, giving $(x - 2)^2 + (y + 3)^2 = 169$. The answer $(x + 2)^2 + (y - 3)^2 = 169$ uses wrong signs for the center coordinates. The answer with $13$ on the right side uses the radius instead of the radius squared. The answer centered at $(14, 2)$ uses the point on the circle as the center.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29P013J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The mean of six numbers is $19$. If a seventh number, $47$, is added to the set, what is the mean of all seven numbers?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The sum of the original six numbers is $6 \\times 19 = 114$. Adding $47$ gives a new sum of $114 + 47 = 161$. The mean of all seven numbers is $\\frac{161}{7} = 23$. A common error is averaging $19$ and $47$ to get $33$, which ignores the different weights of the original set and the new value.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29QXOLM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f(x) = -3x + 17$ models the number of gallons of water remaining in a tank after $x$ hours. What does the value $-3$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The tank loses 3 gallons per hour."},{"key":"B","text":"The tank starts with 3 gallons of water."},{"key":"C","text":"The tank gains 3 gallons per hour."},{"key":"D","text":"The tank will be empty after 3 hours."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $f(x) = -3x + 17$, the coefficient $-3$ is the rate of change (slope), indicating that the water level decreases by $3$ gallons each hour. The interpretation that the tank gains $3$ gallons per hour ignores the negative sign. The claim that the tank starts with $3$ gallons confuses the slope with the initial value, which is $17$. The claim that the tank empties after $3$ hours confuses the rate of change with the time to depletion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXAQC7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A machine fills $7$ bottles every $4$ minutes. At this constant rate, how many bottles does the machine fill in $28$ minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49', ARRAY['49'], E'The machine fills $7$ bottles per $4$ minutes. In $28$ minutes, the number of $4$-minute intervals is $\\frac{28}{4} = 7$. Multiplying, $7 \\times 7 = 49$ bottles. The answer is $49$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B72QKZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between the number of hours studied and test scores. Which of the following best describes this relationship?', NULL, $lyceon_json$[{"key":"A","text":"As hours studied increases, test scores tend to decrease."},{"key":"B","text":"As hours studied increases, test scores tend to increase."},{"key":"C","text":"There is no relationship between hours studied and test scores."},{"key":"D","text":"As hours studied increases, test scores remain constant."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong positive linear association means that as one variable increases, the other also tends to increase. Therefore, as hours studied increases, test scores tend to increase. The choice stating scores tend to decrease describes a negative association. The choice stating no relationship contradicts the given strong association. The choice stating scores remain constant describes no correlation.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"graph_read_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BC73TT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{3}{5}$ cup of oil for every $11$ servings. How many cups of oil are needed for $77$ servings?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{21}{5}$"},{"key":"B","text":"$\\frac{33}{5}$"},{"key":"C","text":"$\\frac{77}{5}$"},{"key":"D","text":"$\\frac{3}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the scale factor: $\\frac{77}{11} = 7$. Then multiply the oil amount: $\\frac{3}{5} \\times 7 = \\frac{21}{5}$. The correct answer is $\\frac{21}{5}$. The value $\\frac{33}{5}$ results from incorrectly multiplying $\\frac{3}{5} \\times 11$ instead of using the ratio. The value $\\frac{77}{5}$ comes from dividing $77$ by $5$ without applying the recipe ratio. The value $\\frac{3}{5}$ reflects stopping at the per-batch amount without scaling up.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
