INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BIN98L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $5$ centimeters and a height of $12$ centimeters. What is the volume of the cylinder, in cubic centimeters? (Give your answer in terms of $\\pi$, expressed as the coefficient of $\\pi$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '300', ARRAY['300'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 5$ and $h = 12$: $V = \\pi (5)^2 (12) = \\pi (25)(12) = 300\\pi$ cubic centimeters. The coefficient of $\\pi$ is $300$. A common error is using the diameter instead of the radius, which would give $\\pi (10)^2 (12) = 1200\\pi$. Another error is computing $\\pi r h$ instead of $\\pi r^2 h$, yielding $60\\pi$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BKYY8O', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 11)$ and $(5, 23)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The slope of the line is $\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4$. Using point-slope form with the point $(2, 11)$: $y - 11 = 4(x - 2)$, which simplifies to $y = 4x + 3$. The $y$-intercept is $3$. A common error is computing the slope as $\\frac{5 - 2}{23 - 11} = \\frac{1}{4}$, which inverts the rise and run. Another error is stopping at the slope without finding the intercept.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BN3VBD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'In a class of 37 students, 19 study French, 23 study Spanish, and 11 study both French and Spanish. If a student is selected at random from those who study Spanish, what is the probability that the student also studies French?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/23', ARRAY['11/23', '0.478', '.478'], E'The conditional probability of studying French given that the student studies Spanish is $P(\\text{French} \\mid \\text{Spanish}) = \\frac{P(\\text{French and Spanish})}{P(\\text{Spanish})}$. There are $11$ students who study both and $23$ who study Spanish, so the probability is $\\frac{11}{23}$. A common error is dividing by the total class size of $37$ to get $\\frac{11}{37}$, which gives the unconditional probability of studying both rather than the conditional probability. Another error is using $19$ (French students) as the denominator, which confuses the conditioning event.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BZ7ACR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $3, 7, 7, 9, 14$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set in order is $3, 7, 7, 9, 14$. With $5$ values, the median is the middle (third) value, which is $7$. The value $3$ is the minimum, not the median. The value $8$ results from averaging $7$ and $9$, which would only apply if there were an even number of values. The value $9$ is the fourth value, not the middle one.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C2VZ82', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x - 7) + 5x$?', NULL, $lyceon_json$[{"key":"A","text":"$11x - 21$"},{"key":"B","text":"$11x - 7$"},{"key":"C","text":"$6x - 21$"},{"key":"D","text":"$11x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3(2x - 7) + 5x = 6x - 21 + 5x = 11x - 21$. The expression $11x - 7$ results from failing to distribute the $3$ to the constant term $-7$. The expression $6x - 21$ omits the $+5x$ term. The expression $11x + 21$ applies an incorrect positive sign to the $-21$ constant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EEKC69', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $7x - 11 > 31$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $11$ to both sides gives $7x > 42$, and dividing both sides by $7$ gives $x > 6$. The only value greater than $6$ among the choices is $7$. The value $6$ fails because the inequality is strict ($>$, not $\\geq$), representing incomplete reasoning about the boundary. The value $5$ results from an arithmetic slip when dividing. The value $4$ could arise from a sign error when rearranging the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GA5J3R', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'What is the minimum value of the function $f(x) = (x - 3)^2 + 7$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $f(x) = (x - 3)^2 + 7$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, so the parabola opens upward and has a minimum at $k = 7$. The value $3$ confuses the $x$-coordinate of the vertex with the minimum output value. The values $-3$ and $-7$ apply incorrect signs to the vertex coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GDWLMF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$ centimeters. What is the radius of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$26$"},{"key":"C","text":"$52$"},{"key":"D","text":"$169$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius of a circle is half the diameter. Therefore, the radius is $\\frac{26}{2} = 13$ centimeters. The answer $26$ confuses radius with diameter. The answer $52$ doubles the diameter instead of halving it. The answer $169$ computes $13^2$, which would be relevant for area but not for the radius itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
