INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H0DP32', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A class of $23$ students has a mean test score of $78$. A second class of $17$ students has a mean test score of $86$. What is the mean test score for all $40$ students combined?', NULL, $lyceon_json$[{"key":"A","text":"$81.4$"},{"key":"B","text":"$82$"},{"key":"C","text":"$82.6$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total score for the first class is $23 \\times 78 = 1{,}794$ and for the second class is $17 \\times 86 = 1{,}462$. The combined total is $1{,}794 + 1{,}462 = 3{,}256$. The combined mean is $\\frac{3256}{40} = 81.4$. The value $82$ results from simply averaging $78$ and $86$ without weighting by class size. The value $82.6$ comes from reversing the class sizes when weighting ($17 \\times 78 + 23 \\times 86$). The value $81$ results from an arithmetic rounding error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H1BF8S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone and a cylinder have the same radius of $6$ centimeters and the same height of $11$ centimeters. What is the positive difference between the volume of the cylinder and the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$132\\pi$"},{"key":"B","text":"$264\\pi$"},{"key":"C","text":"$396\\pi$"},{"key":"D","text":"$66\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of the cylinder is $V_{\\text{cyl}} = \\pi r^2 h = \\pi (6)^2 (11) = 396\\pi$. The volume of the cone is $V_{\\text{cone}} = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(396\\pi) = 132\\pi$. The difference is $396\\pi - 132\\pi = 264\\pi$. The answer $132\\pi$ gives only the volume of the cone rather than the difference. The answer $396\\pi$ gives only the volume of the cylinder. The answer $66\\pi$ incorrectly computes $\\frac{1}{6}\\pi r^2 h$ instead of the correct difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HR0E6S', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A bakery charges $\\$3$ for each muffin and $\\$5$ for each scone. A customer wants to spend no more than $\\$47$ and must buy at least $1$ scone. What is the maximum number of muffins the customer can buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'Let $m$ be the number of muffins and $s$ the number of scones. The constraints are $3m + 5s \\leq 47$ and $s \\geq 1$. To maximize $m$, minimize $s$ by setting $s = 1$. Then $3m + 5 \\leq 47$, so $3m \\leq 42$, giving $m \\leq 14$. The maximum number of muffins is $14$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
