INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I5P9B7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If the expression $\\frac{14x^3 y^5}{7x y^2}$ can be written as $ax^b y^c$ where $a$, $b$, and $c$ are positive constants, what is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Simplify by dividing coefficients and subtracting exponents: $\\frac{14x^3 y^5}{7x y^2} = 2x^{3-1}y^{5-2} = 2x^2 y^3$. So $a = 2$, $b = 2$, and $c = 3$, giving $a + b + c = 2 + 2 + 3 = 7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IQ2IN1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, side $AB = 11$, side $BC = 17$, and side $AC = 23$. Which of the following correctly lists the angles of the triangle from smallest to largest?', NULL, $lyceon_json$[{"key":"A","text":"$\\angle A, \\angle B, \\angle C$"},{"key":"B","text":"$\\angle C, \\angle A, \\angle B$"},{"key":"C","text":"$\\angle B, \\angle A, \\angle C$"},{"key":"D","text":"$\\angle C, \\angle B, \\angle A$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a triangle, the largest angle is opposite the longest side and the smallest angle is opposite the shortest side. The sides in increasing order are $AB = 11$, $BC = 17$, $AC = 23$. The angle opposite $AB$ is $\\angle C$, the angle opposite $BC$ is $\\angle A$, and the angle opposite $AC$ is $\\angle B$. Therefore, the angles from smallest to largest are $\\angle C, \\angle A, \\angle B$. Listing $\\angle A, \\angle B, \\angle C$ ignores the side-angle relationship entirely. Listing $\\angle B, \\angle A, \\angle C$ reverses the ordering of the two smaller angles. Listing $\\angle C, \\angle B, \\angle A$ reverses the relationship, placing the largest angle opposite the shortest side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JB1WYR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs $\\$85$. If the jacket is on sale for $40\\%$ off, what is the sale price?', NULL, $lyceon_json$[{"key":"A","text":"$\\$34$"},{"key":"B","text":"$\\$45$"},{"key":"C","text":"$\\$51$"},{"key":"D","text":"$\\$55$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $40\\%$ discount on $\\$85$ is $0.40 \\times 85 = \\$34$. The sale price is $85 - 34 = \\$51$. The value $\\$34$ is the discount amount, not the sale price. The value $\\$45$ results from an arithmetic error when subtracting. The value $\\$55$ comes from miscalculating the percentage.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JBSNDW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{9x^2 - 49}{3x^2 + 2x - 21}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3x + 7}{x + 3}$"},{"key":"B","text":"$\\frac{3x - 7}{x + 3}$"},{"key":"C","text":"$\\frac{3x + 7}{x - 3}$"},{"key":"D","text":"$\\frac{3x - 7}{x - 3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator is a difference of squares: $9x^2 - 49 = (3x - 7)(3x + 7)$. The denominator factors as $3x^2 + 2x - 21 = (3x - 7)(x + 3)$, since $(3x)(x) = 3x^2$, $(3x)(3) + (-7)(x) = 9x - 7x = 2x$, and $(-7)(3) = -21$. Canceling the common factor $(3x - 7)$ yields $\\frac{3x + 7}{x + 3}$. The expression $\\frac{3x - 7}{x + 3}$ results from canceling the wrong factor from the numerator. The expression $\\frac{3x + 7}{x - 3}$ arises from a sign error when factoring the denominator. The expression $\\frac{3x - 7}{x - 3}$ reflects errors in both the cancellation and the denominator factoring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JSRTOB', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZ20EV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 340 residents of a city found that $57\\%$ prefer expanded bus routes. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $57\\%$ of all city residents prefer expanded bus routes."},{"key":"B","text":"About $57\\%$ of the 340 residents surveyed prefer expanded bus routes, but nothing can be concluded about all residents."},{"key":"C","text":"It is plausible that about $57\\%$ of all city residents prefer expanded bus routes."},{"key":"D","text":"More than half of residents who ride buses prefer expanded routes."}]$lyceon_json$::jsonb, 'C', NULL, E'Because the sample was randomly selected, the sample statistic of $57\\%$ can be used to estimate the corresponding population parameter, making it plausible that about $57\\%$ of all residents prefer expanded bus routes. The claim that exactly $57\\%$ of all residents hold this preference overstates the precision of a sample estimate. The statement that nothing can be concluded about all residents ignores the purpose of random sampling, which is to make inferences about the population. The claim about residents who ride buses introduces a subgroup not identified in the survey.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3DVKG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'What is the solution to $\\sqrt{3x + 7} = x - 1$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Squaring both sides gives $3x + 7 = (x - 1)^2 = x^2 - 2x + 1$. Rearranging: $x^2 - 5x - 6 = 0$, which factors as $(x - 6)(x + 1) = 0$, giving $x = 6$ or $x = -1$. Check $x = 6$: $\\sqrt{3(6) + 7} = \\sqrt{25} = 5$ and $6 - 1 = 5$. This is valid. Check $x = -1$: $\\sqrt{3(-1) + 7} = \\sqrt{4} = 2$ and $-1 - 1 = -2$. Since $2 \\neq -2$, this is an extraneous solution introduced by squaring. The only solution is $6$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KR6Z1E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She randomly assigns 46 tomato plants to receive the new fertilizer and 46 to receive no fertilizer. After 8 weeks, she compares the average yield of the two groups. Which of the following best describes this study?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the researcher measured the yields of the plants"},{"key":"B","text":"A survey, because data was collected from two groups of plants"},{"key":"C","text":"An observational study, because the plants could not provide consent"},{"key":"D","text":"An experiment, because a treatment was randomly assigned to subjects"}]$lyceon_json$::jsonb, 'D', NULL, E'This is an experiment because the researcher deliberately imposed a treatment (the fertilizer) and randomly assigned subjects (tomato plants) to treatment and control groups. The description as an observational study because yields were measured confuses collecting data (which all studies do) with observational study design, where no treatment is imposed. Calling it a survey misapplies terminology, since surveys collect self-reported information from human respondents. The claim that the study is observational because plants cannot consent is irrelevant — the defining feature of an experiment is random assignment of a treatment, not the consent of subjects.', $lyceon_json${"D":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KYQHO0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $9$ and the hypotenuse has length $41$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$40$"},{"key":"C","text":"$42$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem, $a^2 + b^2 = c^2$, so $9^2 + b^2 = 41^2$, giving $81 + b^2 = 1681$, thus $b^2 = 1600$ and $b = 40$. The answer $32$ comes from subtracting rather than using the Pythagorean theorem ($41 - 9 = 32$). The answer $42$ results from an arithmetic error in computing $\\sqrt{1600}$. The answer $50$ comes from adding the squares instead of subtracting ($81 + 1681 = 1762$, then approximating the root).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LTZJUY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'grid_in', E'A bag contains 7 red marbles, 11 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/21', ARRAY['11/21', '0.523', '.523', '0.524', '.524'], E'There are $7 + 11 + 3 = 21$ marbles in total, and $11$ of them are blue. The probability of selecting a blue marble is $\\frac{11}{21}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSGPX4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 registered voters found that $47\\%$ support a ballot measure. The margin of error for the estimate is $4.3$ percentage points. Which of the following is the most accurate statement based on these results?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $47\\%$ of all registered voters support the ballot measure."},{"key":"B","text":"The proportion of all registered voters who support the measure is plausibly between $42.7\\%$ and $51.3\\%$."},{"key":"C","text":"Between $42.7\\%$ and $51.3\\%$ of the 400 voters surveyed support the measure."},{"key":"D","text":"The proportion of all registered voters who support the measure is plausibly between $44.7\\%$ and $49.3\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $47\\% \\pm 4.3\\%$, which gives a range of $42.7\\%$ to $51.3\\%$. This interval estimates the population parameter, not the sample statistic, so the statement that the proportion of all registered voters is plausibly in this range is correct. The claim that exactly $47\\%$ of all voters support the measure ignores sampling variability. Applying the interval to the 400 surveyed voters confuses the sample with the population — the sample proportion is known to be $47\\%$. The range $44.7\\%$ to $49.3\\%$ results from using only half of the margin of error ($2.15$ instead of $4.3$).', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NG0B7R', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x + 3y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$\\frac{21}{5}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting $x = 0$ into $5(0) + 3y = 21$ gives $3y = 21$, so $y = 7$. The value $21$ results from reading the constant term without dividing by the coefficient of $y$. The value $\\frac{21}{5}$ comes from finding the $x$-intercept instead of the $y$-intercept. The value $3$ results from mistaking the coefficient of $y$ for the intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P8ECAX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up a product by $60\\%$ over its wholesale cost and then offers a $25\\%$ discount on the marked-up price. If the final selling price is $\\$54$, what is the wholesale cost of the product?', NULL, $lyceon_json$[{"key":"A","text":"$\\$40$"},{"key":"B","text":"$\\$45$"},{"key":"C","text":"$\\$48$"},{"key":"D","text":"$\\$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the wholesale cost be $w$. The marked-up price is $1.6w$. After a $25\\%$ discount, the selling price is $0.75 \\times 1.6w = 1.2w$. Setting $1.2w = 54$ gives $w = \\frac{54}{1.2} = 45$. The wholesale cost is $\\$45$. The value $\\$40$ results from incorrectly setting up the equation as $1.35w = 54$. The value $\\$48$ comes from only applying the discount without the markup. The value $\\$36$ arises from treating the $60\\%$ markup and $25\\%$ discount as a net $35\\%$ markup on the final price.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QP6O4N', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 + 9x + 11 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 9^2 - 4(2)(11) = 81 - 88 = -7$. Since the discriminant is negative, the equation has $0$ real solutions. The answer $1$ reflects confusion with the condition for a repeated root, which requires the discriminant to equal zero. The answer $2$ assumes every quadratic equation has two real solutions. The answer $4$ misinterprets the structure of the problem.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
