INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R9H54X', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $\\frac{2x + 5}{3} = \\frac{4x - 1}{7}$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-19$"},{"key":"B","text":"$-38$"},{"key":"C","text":"$1$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'A', NULL, E'Cross-multiplying gives $7(2x + 5) = 3(4x - 1)$, which expands to $14x + 35 = 12x - 3$. Subtracting $12x$ from both sides yields $2x + 35 = -3$, and subtracting $35$ gives $2x = -38$. Dividing by $2$ produces $x = -19$. The value $-38$ results from stopping at $2x = -38$ without dividing by $2$. The value $19$ comes from dropping the negative sign when dividing $-38$ by $2$. The value $1$ results from reversing the cross-multiplication, computing $3(2x + 5) = 7(4x - 1)$ and solving incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZEIP7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has the equation $(x - 5)^2 + (y + 7)^2 = 121$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $(h, k)$ is the center and $r$ is the radius. Comparing with $(x - 5)^2 + (y + 7)^2 = 121$, we identify $r^2 = 121$, so $r = \\sqrt{121} = 11$. A common error is reporting $121$ as the radius instead of taking the square root, or confusing the center coordinates with the radius.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V578C4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and value (in thousands of dollars) of $19$ used cars of the same model. The line of best fit is $v = -1.7a + 23.8$, where $v$ is the predicted value and $a$ is the age. A car that is $8$ years old has an actual value of $\\$12{,}300$. What is the residual for this car, in thousands of dollars?', NULL, $lyceon_json$[{"key":"A","text":"$2.1$"},{"key":"B","text":"$-2.1$"},{"key":"C","text":"$1.7$"},{"key":"D","text":"$-1.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value for an $8$-year-old car is $v = -1.7(8) + 23.8 = -13.6 + 23.8 = 10.2$ thousand dollars. The actual value is $12.3$ thousand dollars. The residual is actual minus predicted: $12.3 - 10.2 = 2.1$ thousand dollars. The value $-2.1$ results from computing predicted minus actual instead of actual minus predicted. The value $1.7$ confuses the residual with the slope of the line. The value $-1.7$ similarly confuses the residual with the negative slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XBWCZ6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring gives $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. The positive solution is $4$. The value $3$ results from an arithmetic slip in identifying the factors. The value $7$ comes from using the magnitude of the negative root and neglecting its sign. The value $14$ may arise from confusing the sum or product of roots with a solution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XC3JU6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A ladder leans against a vertical wall, making an angle of $67^\\circ$ with the ground. If the base of the ladder is $3.9$ meters from the wall, what is the length of the ladder, in meters? (Round your answer to the nearest hundredth. Use $\\cos(67^\\circ) \\approx 0.3907$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9.98', ARRAY['9.98'], E'The base of the ladder, the wall, and the ladder form a right triangle. The distance from the base of the ladder to the wall is the adjacent side to the $67^\\circ$ angle, and the ladder is the hypotenuse. Using $\\cos(67^\\circ) = \\frac{\\text{adjacent}}{\\text{hypotenuse}}$, we get $0.3907 = \\frac{3.9}{L}$. Solving for $L$: $L = \\frac{3.9}{0.3907} \\approx 9.98$ meters. A common error is using sine instead of cosine, which would give a different result. Another error is multiplying $3.9 \\times 0.3907$ instead of dividing.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XCIKFB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The equation of line $p$ is $7x - 2y = 18$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting $7x - 2y = 18$ in slope-intercept form gives $y = \\frac{7}{2}x - 9$, so the slope of line $p$ is $\\frac{7}{2}$. The slope of a perpendicular line is the negative reciprocal: $-\\frac{2}{7}$. Using the point $(7, -3)$: $-3 = -\\frac{2}{7}(7) + b$, which gives $-3 = -2 + b$, so $b = -1$. The value $1$ results from a sign error when solving $-3 = -2 + b$ as $b = -3 + 2 = -1$ but then dropping the negative. The value $-3$ comes from using the $y$-coordinate of the given point as the intercept without calculation. The value $-5$ comes from computing $b = -3 - 2 = -5$ instead of $b = -3 + 2 = -1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y8AC31', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'A scientist models the concentration of a substance with $C(t) = 200 \\cdot \\left(\\frac{1}{2}\\right)^{t/9}$, where $t$ is measured in hours. After exactly how many hours will the concentration equal $25$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27', ARRAY['27'], E'Set $C(t) = 25$: $200 \\cdot \\left(\\frac{1}{2}\\right)^{t/9} = 25$. Dividing both sides by $200$ gives $\\left(\\frac{1}{2}\\right)^{t/9} = \\frac{25}{200} = \\frac{1}{8}$. Since $\\frac{1}{8} = \\left(\\frac{1}{2}\\right)^3$, we have $\\frac{t}{9} = 3$, so $t = 27$. The concentration equals $25$ after exactly $27$ hours.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YCNH6I', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ if $7x - 19 = 30$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Solving $7x - 19 = 30$, add $19$ to both sides to get $7x = 49$. Dividing both sides by $7$ gives $x = 7$. A common error is subtracting $19$ instead of adding, which would yield $7x = 11$ and a non-integer result. Another error is dividing $30$ by $7$ without first isolating the variable term.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YHISFD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 5 \\cdot 3^x$. Which of the following is equivalent to $f(x + 2) - f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$2f(x)$"},{"key":"B","text":"$8f(x)$"},{"key":"C","text":"$9f(x)$"},{"key":"D","text":"$6f(x)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Compute $f(x + 2) = 5 \\cdot 3^{x+2} = 5 \\cdot 3^x \\cdot 3^2 = 9 \\cdot f(x)$. Then $f(x+2) - f(x) = 9f(x) - f(x) = 8f(x)$. The expression $2f(x)$ mistakes the additive shift in the exponent for a multiplicative factor of $2$. The expression $9f(x)$ gives $f(x+2)$ itself without subtracting $f(x)$. The expression $6f(x)$ results from using $3^2 = 6$ instead of $9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YI8OBN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$, the right angle is at vertex $E$. If $\\sin(D) = \\frac{7}{25}$, what is the value of $\\cos(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{24}{25}$"},{"key":"B","text":"$\\frac{7}{24}$"},{"key":"C","text":"$\\frac{18}{25}$"},{"key":"D","text":"$\\frac{25}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\sin(D) = \\frac{7}{25}$, the side opposite angle $D$ is $7$ and the hypotenuse is $25$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$. Therefore $\\cos(D) = \\frac{24}{25}$. The answer $\\frac{7}{24}$ confuses cosine with tangent. The answer $\\frac{18}{25}$ results from computing $25 - 7 = 18$ instead of using the Pythagorean theorem. The answer $\\frac{25}{7}$ incorrectly takes the reciprocal of $\\sin(D)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YYDP7S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'grid_in', E'In triangle $PQR$, the measure of angle $P$ is $53^\\circ$ and the measure of angle $Q$ is $71^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '56', ARRAY['56'], E'The sum of interior angles in a triangle is $180^\\circ$. Therefore, angle $R = 180^\\circ - 53^\\circ - 71^\\circ = 56^\\circ$. A common error is to subtract only one angle from $180^\\circ$, yielding $127^\\circ$ or $109^\\circ$, but the correct calculation requires subtracting both known angles.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW204MEO6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although researchers have long known that the axolotl, a salamander native to Lake Xochimilco in central _____ can regenerate entire limbs, a 2022 study revealed that the animal''s regenerative capacity extends to portions of its brain, a finding that could have significant implications for neuroscience.', $lyceon_json$[{"key":"A","text":"Mexico can"},{"key":"B","text":"Mexico, can"},{"key":"C","text":"Mexico; can"},{"key":"D","text":"Mexico—can"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice places a comma after "Mexico" to close the nonrestrictive appositive "a salamander native to Lake Xochimilco in central Mexico." This appositive was opened by a comma after "axolotl," so a matching comma is required to close it before the main clause continues with "can regenerate." Omitting the closing comma fails to properly set off the appositive and creates an unclear sentence boundary. A semicolon is inappropriate because there is no independent clause preceding it—the text up to this point is part of the subordinate "Although" clause. An em dash does not match the opening comma; paired punctuation marks must be consistent (comma with comma, or dash with dash).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20G02WN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'The philosopher Kwame Anthony Appiah has argued that the concept of distinct racial identities, far from being a fixed biological reality, emerged largely through colonial administrative practices of the eighteenth and nineteenth centuries. Census categories, legal codes, and land-tenure systems required officials to sort populations into discrete groups, and these bureaucratic labels gradually hardened into social identities that people internalized and defended. Appiah cautions, however, that recognizing the constructed nature of race does not diminish its present-day consequences. Because institutions, economic structures, and cultural narratives have been organized around racial categories for centuries, those categories continue to shape material outcomes even after their arbitrary origins are exposed.', $lyceon_json$[{"key":"A","text":"Appiah contends that racial categories were constructed through colonial bureaucracy yet remain consequential because institutions have long been organized around them."},{"key":"B","text":"Appiah believes that exposing the arbitrary origins of racial categories will eventually eliminate racial inequality."},{"key":"C","text":"Appiah argues that colonial census practices were the most harmful aspect of European imperialism."},{"key":"D","text":"Appiah maintains that racial identities are biologically grounded but have been distorted by colonial administrative systems."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage makes two linked claims: racial categories arose from colonial administrative sorting, and despite their constructed origins, they still produce real consequences because institutions have been built around them. The choice stating that racial categories were constructed through colonial bureaucracy yet remain consequential captures both elements. The claim that exposing arbitrary origins will eliminate inequality contradicts Appiah''s caution that consequences persist even after origins are exposed. The choice about census practices being the most harmful aspect of imperialism introduces a comparative judgment the passage never makes. The choice asserting biological grounding directly contradicts the passage''s opening point that race is not a fixed biological reality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW219E8CJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a later section of the article, if included, would most effectively support the claim made in the text?', E'A 2023 study published in the journal Cognitive Development found that bilingual children aged 4 to 6 outperformed monolingual peers on tasks requiring attentional control—the ability to focus on relevant information while ignoring distractions. The study''s authors attribute this advantage to the constant practice bilingual children get in suppressing one language while using the other, a process that strengthens domain-general executive functions.', $lyceon_json$[{"key":"A","text":"\"Neuroimaging data revealed that bilingual children showed greater activation in the dorsolateral prefrontal cortex, a region associated with inhibitory control, during conflict-monitoring tasks.\""},{"key":"B","text":"\"Bilingual children in the study came from households with higher average income levels, a factor that has independently been linked to cognitive development.\""},{"key":"C","text":"\"Monolingual children in the control group scored higher on vocabulary breadth measures in their single language than bilingual children scored in either of theirs.\""},{"key":"D","text":"\"The researchers acknowledged that their sample of 83 children, drawn from a single metropolitan area, may not be representative of bilingual populations worldwide.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims that bilingual children''s language-suppression practice strengthens executive functions such as attentional control. The quotation about greater activation in the dorsolateral prefrontal cortex during conflict-monitoring tasks provides neurological evidence for this mechanism, directly supporting the claim. The quotation about higher household income introduces a confounding variable that could weaken the claim by offering an alternative explanation. The quotation about monolingual children''s vocabulary scores addresses a different cognitive dimension unrelated to attentional control. The quotation about sample limitations raises methodological concerns that would qualify, not support, the study''s findings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2400YMU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a report on urban heat islands, a student wants to present a contrast between the problem and a potential solution. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27EJSE6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A coalition of marine conservation organizations _____ advocating for stricter regulations on deep-sea trawling in the North Atlantic. The groups argue that current fishing practices have caused irreversible damage to fragile coral ecosystems on the ocean floor.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"have been"},{"key":"D","text":"were"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "is" because the subject of the sentence is "A coalition," which is singular. The prepositional phrase "of marine conservation organizations" modifies "coalition" but does not change the number of the subject. The singular subject requires a singular verb. "Are" is a plural verb that incorrectly agrees with the plural noun "organizations" rather than the true subject. "Have been" uses a plural auxiliary verb, making the same agreement error. "Were" is both plural and past tense, conflicting with the singular subject and the present-tense context established by "argue" in the following sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW287DK2S', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Bergen recently examined the behavior of Arctic terns during their annual migration from the Arctic to the Antarctic. By attaching miniature tracking devices to 47 terns, the team documented that the birds do not follow a direct north-south route as previously assumed. Instead, the terns exploit prevailing wind patterns over the Atlantic, tracing an elongated S-shaped path that adds roughly 9,000 kilometers to their journey but reduces overall energy expenditure by an estimated 23 percent.', $lyceon_json$[{"key":"A","text":"Arctic terns migrate farther than any other bird species on Earth."},{"key":"B","text":"Arctic terns follow a wind-assisted route that increases distance but conserves energy."},{"key":"C","text":"Miniature tracking devices have transformed the study of bird migration patterns."},{"key":"D","text":"Arctic tern populations are declining because of changes in Atlantic wind patterns."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on the finding that Arctic terns take an S-shaped route exploiting wind patterns, which adds distance but cuts energy use by roughly 23 percent. The choice stating that terns follow a wind-assisted route that increases distance but conserves energy captures this central idea. The claim about migrating farther than any other species is not stated in the passage, which discusses route shape rather than comparative distance records. The choice about tracking devices focuses on methodology rather than the passage''s main finding. The choice about declining populations introduces a consequence not mentioned anywhere in the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29CNHPK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the argument presented in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A2J4S8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Architect Yuki Tanaka designed the Harmon Civic Library in 2017 as part of a municipal revitalization initiative in Newfield, Oregon. The _____ features a cantilevered reading room that extends over a public courtyard, providing shade in summer and shelter from rain during the region''s long wet season.', $lyceon_json$[{"key":"A","text":"building, which won a regional design award that year,"},{"key":"B","text":"building which won a regional design award that year"},{"key":"C","text":"building which won a regional design award that year,"},{"key":"D","text":"building, which won a regional design award that year"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is the one that places commas on both sides of the nonrestrictive clause "which won a regional design award that year." Because this clause provides additional, nonessential information about the building, it must be set off by a pair of commas. The version with no commas at all incorrectly treats the clause as restrictive. The version with a comma only after the clause omits the necessary opening comma. The version with a comma only before the clause omits the necessary closing comma, incorrectly separating the subject from its verb.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AR4XLI', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The philosopher Hypatia of Alexandria, active in the late fourth and early fifth centuries, lectured on mathematics and Neoplatonist thought to audiences that included both pagans and Christians. Her intellectual authority was widely acknowledged; the Roman prefect Orestes reportedly consulted her on civic matters. __________ some historians caution that later Christian chroniclers may have inflated accounts of her influence to serve their own polemical narratives about the relationship between secular learning and religious authority.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"That said,"},{"key":"C","text":"In other words,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "That said," because the final sentence introduces a qualification: while the preceding sentences establish Hypatia''s reputation, the concluding sentence warns that the historical record may be exaggerated. This is a concessive relationship — the author acknowledges Hypatia''s stature but then tempers that acknowledgment. "Furthermore" incorrectly signals that the caveat about chroniclers adds to the case for Hypatia''s influence, when it actually undermines the reliability of that case. "In other words" incorrectly signals a restatement of the same idea, but the final sentence introduces a new, qualifying claim rather than rephrasing an earlier one. "As a result" incorrectly implies that Hypatia''s influence caused historians to question the chronicles, reversing the logical direction of the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ASQMNH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethiopian distance runner Kalkidan Beyene broke the national record in the 10,000 meters at a competition in Brussels in March 2023. Her finishing time of 29 minutes and 43 _____ the previous record had stood for nearly a decade.', $lyceon_json$[{"key":"A","text":"seconds was remarkable, however,"},{"key":"B","text":"seconds was remarkable; however,"},{"key":"C","text":"seconds was remarkable however,"},{"key":"D","text":"seconds was remarkable, however"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon before the conjunctive adverb "however" and a comma after it. When "however" connects two independent clauses, a semicolon must precede it and a comma must follow it. The version using only a comma before "however" and a comma after it creates a comma splice, because a comma alone cannot join two independent clauses. The version with no punctuation before "however" produces a run-on sentence. The version with a comma before "however" but no comma after it both creates a comma splice and omits the required comma after the conjunctive adverb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B5TNKK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about the Alvarez hypothesis for a scientific journal, a student wants to acknowledge the initial skepticism the hypothesis faced while emphasizing that subsequent evidence vindicated it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BD51DL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 1947, the Norwegian explorer Thor Heyerdahl sailed a balsa-wood raft named Kon-Tiki across 6,900 kilometers of the Pacific Ocean, arriving in Polynesia after 101 days at sea. Heyerdahl intended the voyage to demonstrate that ancient South Americans could have settled the Pacific islands using primitive watercraft. __________ genetic and linguistic evidence gathered in subsequent decades has consistently indicated that Polynesia was settled by peoples migrating westward from Southeast Asia, not eastward from South America.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"However,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "However," because the final sentence presents scientific evidence that contradicts Heyerdahl''s hypothesis about South American settlement of Polynesia. The passage shifts from describing Heyerdahl''s claim to presenting findings that undermine it, which is a contrast relationship. "Similarly" falsely signals agreement between the hypothesis and the contradicting evidence. "In addition" falsely signals that the genetic evidence builds on rather than challenges Heyerdahl''s theory. "Specifically" falsely suggests the final sentence elaborates on or narrows the preceding claim rather than opposing it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BXLERJ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since Thomas Hunt Morgan''s experiments in the early 1900s. Its rapid reproductive cycle — a new generation every ten days — allows researchers to observe hereditary changes across dozens of generations in a single year. <u>More recently, scientists have begun using Drosophila to study neurodegenerative diseases such as Alzheimer''s and Parkinson''s.</u> These studies exploit the surprising genetic overlap between fruit flies and humans, with roughly sixty percent of known human disease genes having identifiable counterparts in the Drosophila genome.', $lyceon_json$[{"key":"A","text":"It introduces a newer application of the organism discussed in the passage."},{"key":"B","text":"It challenges the methodology described in the preceding sentence."},{"key":"C","text":"It provides statistical evidence supporting a claim about genetics."},{"key":"D","text":"It explains why the organism was first adopted for laboratory research."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence shifts from Drosophila''s traditional role in genetics labs to its use in neurodegenerative disease research, introducing a newer application. The choice stating it challenges methodology is wrong because the sentence does not criticize or question any method — it adds a new research direction. The choice about statistical evidence is wrong because the statistical detail (sixty percent genetic overlap) appears in the following sentence, not the underlined one. The choice about explaining initial adoption is wrong because the passage''s opening sentence already covers Morgan''s early use; the underlined sentence addresses recent developments.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C83KRN', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1829, the silkworm disease muscardine devastated France''s silk industry, destroying nearly a third of annual cocoon harvests. Naturalist Agostino Bassi spent two decades investigating the cause, eventually demonstrating in 1835 that a parasitic fungus — later named Beauveria bassiana — was responsible. Bassi''s discovery was initially met with skepticism from physicians who maintained that diseases arose spontaneously from internal imbalances. Yet within fifteen years, his fungal theory of contagion had influenced Louis Pasteur and helped catalyze the broader germ theory of disease.', $lyceon_json$[{"key":"A","text":"It presents a problem, describes the investigation that resolved it, and traces the impact of the findings."},{"key":"B","text":"It compares two competing scientific theories and argues that one is superior to the other."},{"key":"C","text":"It narrates a scientist's biography from early education through professional achievements."},{"key":"D","text":"It lists several agricultural diseases and evaluates the effectiveness of various treatments."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage begins with a problem (muscardine devastating the silk industry), describes Bassi''s investigation and discovery of the fungal cause, and then traces the broader impact on germ theory. The choice about comparing two theories is wrong because the passage does not present the spontaneous-generation view as a co-equal theory for comparison; it mentions skepticism briefly as a reaction to Bassi''s work. The choice about narrating a biography is wrong because the passage focuses on a single discovery and its consequences, not on Bassi''s life story. The choice about listing diseases and treatments is wrong because the passage discusses only one disease and does not evaluate any treatments.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CNRCW8', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2024 report on workforce development, economists at the Brookings Institution found that employees who participated in on-the-job mentorship programs were more likely to receive promotions, to negotiate higher starting salaries in subsequent positions, and _____ than employees who relied solely on formal degree credentials.', $lyceon_json$[{"key":"A","text":"they reported greater job satisfaction"},{"key":"B","text":"to report greater job satisfaction"},{"key":"C","text":"reporting greater job satisfaction"},{"key":"D","text":"that they reported greater job satisfaction"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "to report greater job satisfaction" because it maintains the parallel infinitive structure established by the preceding list items: "to receive promotions, to negotiate higher starting salaries..., and to report greater job satisfaction." Each element in the coordinated series must take the same grammatical form. "They reported greater job satisfaction" shifts to an independent clause with a finite verb, breaking the parallel structure. "Reporting greater job satisfaction" uses a gerund-participle form that does not match the infinitive pattern. "That they reported greater job satisfaction" introduces a noun clause, which is grammatically inconsistent with the infinitive phrases in the series.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CY2OSY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "concrete" most nearly mean?', E'In her laboratory notebook, Dr. Vasquez recorded that the initial trials had produced only vague, inconclusive data. After recalibrating her instruments and repeating the experiment under stricter conditions, however, she obtained concrete evidence that the compound accelerated cellular repair. Her colleagues, who had been skeptical, acknowledged that the new results left little room for doubt.', $lyceon_json$[{"key":"A","text":"portable"},{"key":"B","text":"cordial"},{"key":"C","text":"definite"},{"key":"D","text":"ornamental"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contrasts "vague, inconclusive data" with the new results, which "left little room for doubt." The word that fits this context is "definite," meaning certain and clearly established. "Portable" means able to be carried easily, which produces an incoherent reading when describing scientific evidence. "Cordial" means warm and friendly in manner, which is nonsensical when applied to evidence. "Ornamental" means serving a decorative purpose, which has no meaningful connection to the certainty of experimental results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CZK6FP', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Architectural historian Mei-Ling Zhao has documented that many Japanese castles built during the Sengoku period (1467–1615) feature stone walls with a distinctive concave curvature rather than straight vertical faces. Zhao notes that this curvature distributes the lateral force of an earthquake across a wider area of the foundation, reducing the likelihood of collapse. She observes that castles built with straight walls during the same period were far more frequently damaged by seismic events. Zhao therefore concludes that the concave design was ________', $lyceon_json$[{"key":"A","text":"an aesthetic preference borrowed from Chinese fortress architecture."},{"key":"B","text":"a deliberate engineering response to Japan's seismic conditions."},{"key":"C","text":"an unintended byproduct of the stone-cutting techniques available at the time."},{"key":"D","text":"a feature found only in castles commissioned by the most powerful feudal lords."}]$lyceon_json$::jsonb, 'B', NULL, E'Zhao''s reasoning connects the concave curvature to earthquake resistance and notes that straight-walled castles suffered more seismic damage. The logical conclusion is that the design was a deliberate engineering response to seismic conditions. The claim about Chinese aesthetic influence introduces an origin the passage never mentions. Calling the design an unintended byproduct contradicts the passage''s evidence that the curvature has a specific structural advantage, which Zhao treats as purposeful. The claim about powerful feudal lords introduces a social distinction unsupported by anything in the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E8O5T9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The International Astronomical Union''s 2023 resolution on planetary nomenclature stipulates that any celestial body designated as a dwarf planet _____ a stable orbit around a star and sufficient mass for gravitational forces to have shaped it into a roughly spherical form. The resolution further requires that such a body not have cleared its orbital neighborhood of other debris.', $lyceon_json$[{"key":"A","text":"maintains"},{"key":"B","text":"maintain"},{"key":"C","text":"has maintained"},{"key":"D","text":"would maintain"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "maintain" because the mandative subjunctive mood is required after verbs of stipulation and demand such as "stipulates that." In this construction, the verb in the subordinate clause takes its base form regardless of the subject''s number. The second sentence confirms this pattern with "requires that such a body not have cleared," using the same subjunctive structure. "Maintains" is the third-person singular indicative form, which is incorrect after a mandative verb. "Has maintained" is the present perfect indicative, which likewise does not conform to the subjunctive construction. "Would maintain" introduces a conditional mood that is not called for by the stipulative context—the resolution states a requirement, not a hypothetical condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ES2Y4P', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Coral reefs support roughly one-quarter of all marine species despite covering less than one percent of the ocean floor. __________ marine biologists often refer to coral reefs as the "rainforests of the sea."', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "For this reason," because the second sentence explains why biologists use the term "rainforests of the sea" — the reason being that coral reefs harbor immense biodiversity relative to their size. "In contrast" incorrectly signals opposition between two ideas that are logically connected. "For instance" incorrectly signals that the second sentence is an example rather than a consequence. "Nevertheless" incorrectly signals a concession, implying the second sentence contradicts the first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GFGNUC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Coastal Ecology Institute hypothesize that the recent decline in Pacific herring populations along the Oregon coast is primarily caused by rising sea-surface temperatures, which reduce the availability of the zooplankton species that herring depend on during their first three months of life. The researchers note that herring spawning rates have remained stable, suggesting that the population decline occurs after hatching rather than before it.', $lyceon_json$[{"key":"A","text":"Zooplankton density in waters above 14°C is 37 percent lower than in waters below 11°C along the same stretch of coastline."},{"key":"B","text":"Pacific herring populations in Alaska, where sea-surface temperatures have remained stable, have also declined over the same period."},{"key":"C","text":"Adult herring along the Oregon coast have shifted their diet away from zooplankton toward small crustaceans."},{"key":"D","text":"Spawning rates for Pacific herring have declined in regions south of Oregon where temperatures are highest."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis links rising sea-surface temperatures to reduced zooplankton availability and, consequently, to herring decline. The finding that zooplankton density drops substantially in warmer waters directly supports this causal link. The finding about Alaskan herring declining despite stable temperatures would undermine, not support, the temperature-based hypothesis. The observation about adult herring changing diet is irrelevant because the hypothesis concerns juvenile herring in their first three months. The finding about declining spawning rates contradicts the passage''s statement that spawning rates have remained stable, and it addresses a different stage of the herring life cycle than the hypothesis targets.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I705Y1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the text?', E'Philosopher Nadia Orlov has argued that algorithmic recommendation systems do not merely reflect user preferences but actively reshape them. When a streaming platform suggests content based on a listener''s history, it narrows the range of encountered styles, gradually reinforcing existing tastes while suppressing exposure to unfamiliar genres. Orlov concedes that users retain the ability to seek out novel content independently, but she maintains that the cumulative effect of algorithmic filtering is a measurable contraction of cultural consumption patterns — a contraction that, she insists, no individual act of curiosity fully counteracts.', $lyceon_json$[{"key":"A","text":"To present a philosopher's qualified claim that algorithmic systems constrain cultural exposure despite user agency"},{"key":"B","text":"To advocate for regulatory restrictions on streaming platforms' use of recommendation algorithms"},{"key":"C","text":"To contrast two philosophers' opposing views on whether technology limits artistic diversity"},{"key":"D","text":"To demonstrate that listeners who rely on algorithms consume a wider variety of music over time"}]$lyceon_json$::jsonb, 'A', NULL, E'The text presents Orlov''s argument that algorithms reshape preferences and narrow exposure, while conceding that users can seek novel content — making it a qualified claim about constrained cultural exposure despite user agency. The choice about advocating for regulation is wrong because the passage never mentions policy, legislation, or regulatory action. The choice about contrasting two philosophers is wrong because only Orlov''s perspective is presented; no opposing philosopher appears. The choice about wider variety is wrong because it directly contradicts the passage''s central claim of a "measurable contraction of cultural consumption patterns."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JIA3IB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "economy" most nearly mean?', E'Literary critic Seo-yun Park argues that the power of Matsuo Basho''s haiku lies not in ornate imagery but in the economy of his language. By stripping each poem to its essential sensory details — a frog''s splash, the hush of cicadas — Basho compresses vast emotional landscapes into seventeen syllables. Park contends that this restraint demands more of the reader, who must supply the resonance that the poet deliberately withholds.', $lyceon_json$[{"key":"A","text":"thriftiness"},{"key":"B","text":"marketplace"},{"key":"C","text":"conciseness"},{"key":"D","text":"prosperity"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage discusses Basho''s technique of "stripping each poem to its essential sensory details" and "compresses vast emotional landscapes into seventeen syllables," indicating sparing, efficient use of words. "Conciseness" — brevity and efficiency of expression — matches this meaning. "Thriftiness" refers to careful management of money or material resources, not linguistic brevity, producing an incoherent reading about penny-pinching language. "Marketplace" refers to a venue for commercial exchange, which is nonsensical when describing a poet''s language. "Prosperity" means wealth or financial success, which makes no sense in the context of poetic technique.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K4R9I1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The phenomenon known as "linguistic relativity"—the idea that the structure of a language influences its speakers'' perception of the _____ has been debated among cognitive scientists and linguists since the mid-twentieth century, with recent neuroimaging studies reigniting interest in the hypothesis.', $lyceon_json$[{"key":"A","text":"world. Has"},{"key":"B","text":"world, has"},{"key":"C","text":"world—has"},{"key":"D","text":"world; has"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice places a closing em dash after "world" to match the opening em dash that appears after "linguistic relativity." The parenthetical phrase "the idea that the structure of a language influences its speakers'' perception of the world" is set off by paired em dashes, so the closing dash is required before the main clause continues with "has been debated." A period after "world" would create a sentence fragment, because "The phenomenon known as ''linguistic relativity''" lacks a main verb. A comma does not match the opening em dash—paired punctuation marks must be consistent. A semicolon similarly fails to match the opening em dash and would also produce a fragment before the semicolon, since the text preceding it contains no independent clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L6M4W7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing about monarch butterfly migration for a general audience, a student wants to emphasize the remarkable distance the butterflies travel. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NJR7CH', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Soil scientist Adaora Eze studied nitrogen cycling in 14 peatland sites across Scotland. She found that sites where sphagnum moss cover exceeded 70 percent retained nearly twice as much nitrogen as sites where sphagnum cover was below 30 percent. Eze attributes this to sphagnum''s unusually high cation-exchange capacity, which allows it to bind ammonium ions before they can be converted to nitrate and leached away. She notes, however, that at five sites where sphagnum cover was above 70 percent but the water table had been artificially lowered by drainage ditches, nitrogen retention was no better than at low-cover sites. Eze therefore argues that sphagnum''s nitrogen-retention function depends not only on moss abundance but also on ________', $lyceon_json$[{"key":"A","text":"the maintenance of a high water table that keeps the moss physiologically active."},{"key":"B","text":"the total acreage of the peatland in which the moss grows."},{"key":"C","text":"the variety of sphagnum species present at a given site."},{"key":"D","text":"the concentration of nitrate rather than ammonium in the soil."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that high sphagnum cover alone is insufficient for nitrogen retention: sites with abundant sphagnum but artificially lowered water tables showed no retention advantage. The logical inference is that a high water table is also necessary. The choice about total peatland acreage introduces a variable the passage never discusses. The choice about species variety is unsupported; the passage treats sphagnum as a single functional group. The choice about nitrate concentration misreads the mechanism described: sphagnum binds ammonium ions before they become nitrate, so the relevant factor is the moss''s ability to intercept ammonium, not the concentration of nitrate already present.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ONBTGH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In 1934, the composer Ruth Crawford Seeger transcribed over 300 Appalachian folk songs from field recordings made by her husband, the musicologist Charles Seeger. While her transcriptions were initially regarded as merely functional—tools for preserving melodies that might otherwise be lost—musicologists have since recognized that Crawford Seeger''s work was far more interpretive than documentary. She routinely annotated rhythmic subtleties, microtonal inflections, and ornamental patterns that standard notation could not capture, devising her own supplementary symbols to represent them. Her transcriptions thus constitute an early form of ethnomusicological analysis, not just preservation.', $lyceon_json$[{"key":"A","text":"Crawford Seeger's folk song transcriptions are now understood as analytical works rather than simple records of melodies."},{"key":"B","text":"Crawford Seeger's transcription methods were superior to those used by her husband, Charles Seeger."},{"key":"C","text":"Standard musical notation is inadequate for representing the full range of Appalachian folk music."},{"key":"D","text":"The preservation of Appalachian folk songs in the 1930s depended primarily on the efforts of Ruth Crawford Seeger."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces a shift in how Crawford Seeger''s transcriptions are understood: initially seen as functional preservation tools, they are now recognized as interpretive, analytical work. The choice identifying her transcriptions as analytical works rather than simple records directly captures this arc. The claim that her methods were superior to her husband''s is not supported by the text, which mentions Charles Seeger only as the source of field recordings. The choice about standard notation''s inadequacy reflects a detail the passage uses to explain Crawford Seeger''s innovations, but it is not the central point. The choice claiming preservation depended primarily on Crawford Seeger overstates her role; the passage does not assert she was the sole or primary preserver.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OPO73J', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'For nearly two decades, ethnobotanist Dr. Marisol Fuentes _____ traditional plant-based remedies used by Indigenous communities in the Peruvian Amazon. Her upcoming monograph, scheduled for publication next spring, will compile her findings into a comprehensive guide for medical researchers.', $lyceon_json$[{"key":"A","text":"studies"},{"key":"B","text":"had studied"},{"key":"C","text":"has studied"},{"key":"D","text":"will have studied"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "has studied" because the present perfect tense is required when an action began in the past and continues into the present, as signaled by "For nearly two decades." The simple present "studies" fails to convey the duration indicated by "for nearly two decades"—it would describe a habitual action rather than one spanning a specific period. The past perfect "had studied" implies the action was completed before another past event, but the passage describes ongoing work with no such past reference point. The future perfect "will have studied" places the action''s completion in the future, which contradicts the passage''s present-time framing and the indication that the research has been underway for years.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P638NI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly weaken the economist''s argument?', E'Economist Renata Oliveira argues that universal basic income (UBI) programs reduce labor-force participation because they diminish the financial pressure that motivates people to seek employment. She points to a 2019 pilot in a mid-sized Finnish city where employment rates among UBI recipients fell by 4.7 percentage points relative to a control group over two years. Oliveira contends that this pattern would intensify at scale: a nationwide UBI, by removing the stigma associated with being a sole recipient, would further normalize non-employment and amplify the disincentive effect observed in localized trials.', $lyceon_json$[{"key":"A","text":"A three-year nationwide UBI program in Namibia resulted in a 17 percent increase in self-employment and a 9 percent rise in overall labor-force participation among recipients."},{"key":"B","text":"The Finnish pilot that Oliveira cites was later extended for an additional year, during which employment among recipients declined by another 1.2 percentage points."},{"key":"C","text":"Several economists have argued that UBI would be prohibitively expensive to implement at the national level in most high-income countries."},{"key":"D","text":"A survey of Finnish UBI recipients found that 62 percent reported reduced financial anxiety, which Oliveira acknowledges as a secondary benefit of the program."}]$lyceon_json$::jsonb, 'A', NULL, E'Oliveira''s central argument is that UBI reduces labor-force participation and that this effect would intensify when implemented nationwide. The finding from Namibia directly contradicts both elements: a nationwide UBI program produced increased self-employment and higher overall labor-force participation, the opposite of what Oliveira predicts. The finding that the Finnish pilot showed further employment decline in an extended year would strengthen, not weaken, Oliveira''s argument. The objection about cost addresses feasibility rather than the labor-participation claim. The survey finding about reduced financial anxiety concerns a different outcome altogether and is acknowledged by Oliveira herself, so it does not challenge her core contention about employment effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QKCR1S', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSX47M', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the Swiss linguist Ferdinand de Saussure proposed that the Proto-Indo-European language contained phonemes — which he called "coefficients sonantiques" — that had left traces in descendant languages but had no known counterpart in any attested tongue. For decades, his proposal remained purely theoretical, with no direct evidence to confirm or refute it. __________ when the Hittite language was deciphered in 1915, scholars found consonant sounds in exactly the positions Saussure had predicted, transforming his abstract conjecture into one of the most celebrated confirmations in historical linguistics.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Then,"},{"key":"C","text":"Granted,"},{"key":"D","text":"Instead,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Then," because it signals a temporal sequence: the passage moves from decades of unconfirmed theory to the moment when the decipherment of Hittite provided confirmation. The relationship is chronological progression from an earlier state (no evidence) to a later event (discovery of the predicted sounds). "Moreover" incorrectly signals that the Hittite evidence merely adds to the previous point, missing the pivotal shift from unverified hypothesis to confirmed prediction. "Granted" incorrectly signals a concession, implying the author is acknowledging a counterargument, when the final sentence actually resolves the uncertainty described earlier. "Instead" incorrectly signals that the Hittite discovery replaced or contradicted the earlier theoretical status, when it in fact confirmed the theory rather than supplanting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UVXG37', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Literary scholar Tomás Reyes has examined how the Argentine writer Silvina Ocampo uses unreliable child narrators in her short fiction. Reyes observes that in stories such as "The Fury" and "The Prayer," the child narrators report events with meticulous sensory detail—colors, textures, sounds—while consistently failing to grasp the emotional or moral significance of what they describe. Adults in these stories engage in cruelty, deception, or grief, but the child narrators register only surface phenomena, never interpreting motives or consequences. Reyes argues that this technique does not merely reflect a child''s cognitive limitations; rather, the gap between what the narrator perceives and what the reader understands functions as ________', $lyceon_json$[{"key":"A","text":"a satirical commentary on the Argentine literary establishment's preference for realism over experimental fiction."},{"key":"B","text":"an implicit indictment of adult behavior, made more disturbing by the narrator's inability to name what is wrong."},{"key":"C","text":"evidence that Ocampo considered children to be more morally perceptive than adults."},{"key":"D","text":"a stylistic homage to the stream-of-consciousness techniques pioneered by Virginia Woolf."}]$lyceon_json$::jsonb, 'B', NULL, E'Reyes describes a gap between the child narrator''s detailed but uncomprehending perception and the reader''s fuller understanding of the adults'' cruelty, deception, or grief. The passage states this gap is not simply cognitive limitation but serves a deliberate function. The logical completion is that the gap operates as an implicit indictment: the reader perceives the moral horror that the narrator cannot articulate, making the depicted behavior more disturbing. The claim about satirizing the Argentine literary establishment introduces an institutional critique entirely absent from the passage. The suggestion that Ocampo saw children as more morally perceptive contradicts the passage''s point that the child narrators fail to grasp emotional or moral significance. The claim about Woolf''s stream-of-consciousness introduces a stylistic comparison the passage never raises.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VVNGQD', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "arrested" most nearly mean?', E'During the 1947 expedition to the Gobi Desert, paleontologist Yuri Petrenko discovered a fossilized embryo whose development had been arrested at an unusually early stage. Unlike most specimens recovered from the formation, which showed nearly complete skeletal ossification, this embryo retained cartilaginous structures that typically vanish weeks before hatching. The find suggested that some environmental catastrophe had interrupted incubation abruptly.', $lyceon_json$[{"key":"A","text":"detained"},{"key":"B","text":"halted"},{"key":"C","text":"condemned"},{"key":"D","text":"publicized"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes an embryo whose development stopped at an early stage, with the environmental catastrophe having "interrupted incubation abruptly." The word "halted" (stopped or ceased) fits this meaning precisely. "Detained" means held in custody by authorities, which is nonsensical when describing embryonic development. "Condemned" means declared guilty or unfit, which does not describe a biological process being stopped. "Publicized" means made widely known, which produces an incoherent sentence about development being made famous at an early stage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z4V9P4', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1
